Tensor Tensor::einsum(std::string equation, const std::vector<Tensor>& operands, const std::vector<int64_t>& path) {
    for (const auto& t : operands) {
        if (t.defined() && t.device() != (operands.empty() ? Device(DeviceType::CPU) : operands[0].device())) {
            TP_THROW(DeviceMismatchError, "Expected all tensors to be on the same device, but found one (in operands) on " + t.device().toString() + " and another ((operands.empty() ? Device(DeviceType::CPU) : operands[0].device())) on " + (operands.empty() ? Device(DeviceType::CPU) : operands[0].device()).toString());
        }
    }
    {
        static const OperatorHandle __ac_handle = Dispatcher::singleton().findHandle("einsum");
        DispatchKey __ac_key = toAutocastKey(computeDispatchKey((operands.empty() ? Device(DeviceType::CPU) : operands[0].device())));
        if (autocast::is_enabled(__ac_key) && __ac_handle && __ac_handle.getKernel(__ac_key)) {
            return DispatchStub<Tensor, std::string, const std::vector<Tensor>&, const std::vector<int64_t>&>::call(__ac_handle, __ac_key, equation, operands, path);
        }
    }
    return detail::redispatch_einsum_function(equation, operands, path);
}

