Tensor Tensor::masked_select(const Tensor& self, const Tensor& mask) {
    if (self.defined() && self.device() != self.device()) {
            TP_THROW(DeviceMismatchError, "Expected all tensors to be on the same device, but found one (self) on " + self.device().toString() + " and another (self.device()) on " + self.device().toString());
    }
    if (mask.defined() && mask.device() != self.device()) {
            TP_THROW(DeviceMismatchError, "Expected all tensors to be on the same device, but found one (mask) on " + mask.device().toString() + " and another (self.device()) on " + self.device().toString());
    }
    return detail::redispatch_masked_select_function(self, mask);
}

