Tensor Tensor::scaled_dot_product_attention(const Tensor& query, const Tensor& key, const Tensor& value, bool is_causal, int64_t impl) {
    if (query.defined() && query.device() != query.device()) {
            TP_THROW(DeviceMismatchError, "Expected all tensors to be on the same device, but found one (query) on " + query.device().toString() + " and another (query.device()) on " + query.device().toString());
    }
    if (key.defined() && key.device() != query.device()) {
            TP_THROW(DeviceMismatchError, "Expected all tensors to be on the same device, but found one (key) on " + key.device().toString() + " and another (query.device()) on " + query.device().toString());
    }
    if (value.defined() && value.device() != query.device()) {
            TP_THROW(DeviceMismatchError, "Expected all tensors to be on the same device, but found one (value) on " + value.device().toString() + " and another (query.device()) on " + query.device().toString());
    }
    {
        static const OperatorHandle __ac_handle = Dispatcher::singleton().findHandle("scaled_dot_product_attention");
        DispatchKey __ac_key = toAutocastKey(computeDispatchKey(query.device()));
        if (autocast::is_enabled(__ac_key) && __ac_handle && __ac_handle.getKernel(__ac_key)) {
            return DispatchStub<Tensor, const Tensor&, const Tensor&, const Tensor&, bool, int64_t>::call(__ac_handle, __ac_key, query, key, value, is_causal, impl);
        }
    }
    if (GradMode::is_enabled()) {
        static const OperatorHandle ag_handle = Dispatcher::singleton().findHandle("scaled_dot_product_attention");
        DispatchKey ag_key = toAutogradKey(computeDispatchKey(query.device()));
        if (ag_handle && ag_handle.getKernel(ag_key)) {
            return DispatchStub<Tensor, const Tensor&, const Tensor&, const Tensor&, bool, int64_t>::call(ag_handle, ag_key, query, key, value, is_causal, impl);
        }
    }
    return detail::redispatch_scaled_dot_product_attention_function(query, key, value, is_causal, impl);
}

